/* Dash Trap Runtime: the task's tc_TrapCode while the program runs. Exec jumps there in supervisor
   mode with the exception's number on the stack, then its frame. For the errors of a program (2 bus
   error, 3 address error, 4 illegal instruction, 5 division by zero, 6 CHK, 7 TRAPV, 8 privilege
   violation, 10/11 line A/F) the frame is dropped and the program goes on in _dash_trap_recover, in
   user mode on the program's own stack from where main began (what was below is abandoned; above it
   are the frames of the startup and of the Shell, kept for the return): it says what happened and
   where, and ends like Stop. Anything else
   (traps, trace: debuggers) goes to the handler that was there. A program run from the Shell is the
   Shell's process: the old handler is put back at exit (atexit). */
#include <dos/dosextens.h>
#include <exec/execbase.h>
APTR _dash_trap_old = NULL;
volatile ULONG _dash_trap_num = 0, _dash_trap_pc = 0, _dash_trap_addr = 0, _dash_trap_usp = 0;
volatile UBYTE _dash_trap_busy = 0, _dash_trap_010 = 0;
void _dash_trap(void);
void _dash_trap_recover(void) __attribute__((used, noreturn));
__asm__(
"       .text\n"
"       .even\n"
"       .globl  __dash_trap\n"
"__dash_trap:\n"
"       cmpl    #46,sp@\n"
"       bne     7f\n"
"       tstl    __dash_brk_go\n"
"       beq     9f\n"
"       addql   #4,sp\n"
"       movel   __dash_brk_go,sp@(2)\n"
"       rte\n"
"7:     cmpl    #2,sp@\n"
"       bcs     9f\n"
"       cmpl    #11,sp@\n"
"       bhi     9f\n"
"       cmpl    #9,sp@\n"
"       beq     9f\n"
"       tstb    __dash_trap_busy\n"
"       bne     9f\n"
"       moveb   #1,__dash_trap_busy\n"
"       movel   sp@,d0\n"
"       movel   d0,__dash_trap_num\n"
"       lea     sp@(4),a0\n"
"       clrl    __dash_trap_addr\n"
"       tstb    __dash_trap_010\n"
"       bne     2f\n"
"       cmpl    #3,d0\n"
"       bhi     1f\n"
"       movel   a0@(2),__dash_trap_addr\n"
"       movel   a0@(10),__dash_trap_pc\n"
"       lea     a0@(14),a0\n"
"       bra     5f\n"
"1:     movel   a0@(2),__dash_trap_pc\n"
"       lea     a0@(6),a0\n"
"       bra     5f\n"
"2:     movel   a0@(2),__dash_trap_pc\n"
"       moveq   #0,d1\n"
"       movew   a0@(6),d1\n"
"       lsrw    #8,d1\n"
"       lsrw    #4,d1\n"
"       lea     __dash_trap_fsize,a1\n"
"       moveb   a1@(0,d1:w),d1\n"
"       andl    #0xff,d1\n"
"       addl    d1,a0\n"
"5:     movel   a0,sp\n"
"       tstb    __dash_trap_010\n"
"       beq     6f\n"
"       clrw    sp@-\n"
"6:     pea     __dash_trap_recover\n"
"       clrw    sp@-\n"
"       movel   __dash_trap_usp,a0\n"
"       movel   a0,usp\n"
"       rte\n"
"9:     movel   __dash_trap_old,sp@-\n"
"       rts\n"
"       .data\n"
"__dash_trap_fsize:\n"
"       .byte   8,8,12,12,16,0,0,60,58,20,32,92,0,0,0,0\n"
"       .text\n"
);

static void _dash_trap_off(void) {
    struct Task *t = FindTask(NULL);
    if (_dash_trap_old && t->tc_TrapCode == (APTR)_dash_trap) t->tc_TrapCode = _dash_trap_old;
    _dash_trap_old = NULL;
}

/* (not in line: its frame is below main's, the start of the stack the recovery takes; before, 8 KB of
   its own in BSS for every program) */
static __attribute__((noinline)) void _dash_trap_on(void) {
    struct Task *t = FindTask(NULL);
    ULONG here;
    if (_dash_trap_old) return;
    _dash_trap_010 = (SysBase->AttnFlags & AFF_68010) != 0;
    _dash_trap_usp = ((ULONG)&here - 16) & ~3UL;
    _dash_trap_old = t->tc_TrapCode;
    t->tc_TrapCode = (APTR)_dash_trap;
    _dash_atexit(_dash_trap_off);
}

/* Ctrl-C in loops (BREAK_RUNTIME of ./dash --gcc, brk_check of ./dash): Ctrl-C to the program's task is an exec
   exception (SetExcept). _dash_brk_exc sets _dash_brk_flag, which the loops of ./dash --gcc test, and turns the NOPs
   that ./dash puts in its loops (the table that ends in 0) into TRAP #14: the next time round, _dash_trap takes the
   program to _dash_brk_go (its "***Break" and the end). Until then a loop pays for a NOP (./dash) or for testing a
   byte (./dash --gcc). The signal is put back: whatever waits for it still sees it. Tasks of task_start: their
   function ends there (_dash_brk_sub, _dash_task_quit), and the program waits for them at its end. */
volatile UBYTE _dash_brk_flag = 0;
struct Task *_dash_brk_task = NULL;
void (*_dash_brk_go)(void) = NULL;
APTR _dash_brk_subold = NULL;
void (*_dash_brk_subquit)(void) = NULL;
static ULONG *_dash_brk_sites = NULL;
static APTR _dash_brk_oldcode, _dash_brk_olddata;
static ULONG _dash_brk_oldmask;
void _dash_brk_exc(void);
void _dash_brk_sub(void);
ULONG _dash_brk_hit(void) __attribute__((used));
ULONG _dash_brk_hit(void) {
    ULONG *s;
    _dash_brk_flag = 1;
    if (_dash_brk_sites) {
        Forbid();             /* (a task of the program, with more priority, could be on one of them) */
        for (s = _dash_brk_sites; *s; s++) *(volatile UWORD *)*s = 0x4E4E;   /* trap #14 */
        Permit();
        CacheClearU();
    }
    SetSignal(SIGBREAKF_CTRL_C, SIGBREAKF_CTRL_C);
    return 0;                 /* (once is enough: the exception stays off) */
}
__asm__(
"       .text\n"
"       .even\n"
"       .globl  __dash_brk_exc\n"
"__dash_brk_exc:\n"
"       moveml  d1/a0-a1,sp@-\n"
"       jsr     __dash_brk_hit\n"
"       moveml  sp@+,d1/a0-a1\n"
"       rts\n"
"       .globl  __dash_brk_sub\n"
"__dash_brk_sub:\n"
"       cmpl    #46,sp@\n"
"       bne     1f\n"
"       addql   #4,sp\n"
"       movel   __dash_brk_subquit,sp@(2)\n"
"       rte\n"
"1:     movel   __dash_brk_subold,sp@-\n"
"       rts\n"
);

static void _dash_brk_off(void) {
    struct Task *t = _dash_brk_task;
    if (!t || t->tc_ExceptCode != (APTR)_dash_brk_exc) return;
    SetExcept(0, SIGBREAKF_CTRL_C);
    t->tc_ExceptCode = _dash_brk_oldcode;
    t->tc_ExceptData = _dash_brk_olddata;
    if (_dash_brk_oldmask) SetExcept(_dash_brk_oldmask, SIGBREAKF_CTRL_C);
}

/* go: where a loop's TRAP #14 takes the program (without a return address); sites: ./dash's NOPs, or NULL */
void _dash_brk_on(void (*go)(void), ULONG *sites) {
    struct Task *t = FindTask(NULL);
    if (_dash_brk_task) return;
    _dash_brk_task = t;
    if (t->tc_SigExcept & ~SIGBREAKF_CTRL_C) return;   /* the task already has exceptions of its own */
    _dash_brk_go = go;
    _dash_brk_sites = sites;
    _dash_brk_oldcode = t->tc_ExceptCode;
    _dash_brk_olddata = t->tc_ExceptData;
    _dash_atexit(_dash_brk_off);
    t->tc_ExceptCode = (APTR)_dash_brk_exc;
    _dash_brk_oldmask = SetExcept(SIGBREAKF_CTRL_C, SIGBREAKF_CTRL_C) & SIGBREAKF_CTRL_C;
}

/* Where pc is in the program: its hunk (segment) and offset, from the process's segment list */
static BOOL _dash_trap_where(ULONG pc, LONG *hunk, ULONG *offset) {
    struct Process *pr = (struct Process *)FindTask(NULL);
    BPTR seg = 0;
    LONG n;
    if (pr->pr_Task.tc_Node.ln_Type != NT_PROCESS) return FALSE;
    if (pr->pr_CLI) seg = ((struct CommandLineInterface *)BADDR(pr->pr_CLI))->cli_Module;
    if (!seg && pr->pr_SegList) seg = ((BPTR *)BADDR(pr->pr_SegList))[3];
    for (n = 0; seg && n < 1000; n++, seg = *(BPTR *)BADDR(seg)) {
        ULONG *p = (ULONG *)BADDR(seg), start = (ULONG)(p + 1), end = (ULONG)p - 4 + p[-1];
        if (pc >= start && pc < end) { *hunk = n; *offset = pc - start; return TRUE; }
    }
    return FALSE;
}

void _dash_trap_recover(void) {
    static const char *const names[] = { "", "", "error de bus", "direcci\363n impar", "instrucci\363n ilegal",
        "divisi\363n por cero", "CHK fuera de rango", "desbordamiento (TRAPV)", "instrucci\363n privilegiada", "",
        "instrucci\363n de l\355nea A", "instrucci\363n de l\355nea F" };
    ULONG num = _dash_trap_num, pc = _dash_trap_pc, offset = 0;
    LONG hunk = 0;
    const char *what = num < 12 ? names[num] : "excepci\363n";
#ifdef _dash_debug_trap
    _dash_debug_trap(what);
#endif
    if (_dash_trap_where(pc, &hunk, &offset))
        _dash_fail_say("Error: %s (excepci\363n %ld)\nen el programa: hunk %ld + $%lx", (LONG)what, (LONG)num, hunk, (LONG)offset);
    else
        _dash_fail_say("Error: %s (excepci\363n %ld)\nen $%lx, fuera del programa (una librer\355a)", (LONG)what, (LONG)num, (LONG)pc, 0);
#if defined(DASH_MEMCHECK) && defined(_DASH_MEMORY_RUNTIME)
    if (_dash_mc_where && DOSBase && Output()) Printf((CONST_STRPTR)"en %s\n", (_DashP)_dash_mc_where);
#endif
    _dash_exit(20);
    for (;;) ;
}

